import{_ as a,o,c,ag as r}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"equals / hashCode / Comparable / Comparator — Practice Exercises","description":"","frontmatter":{},"headers":[],"relativePath":"java/foundations/equals_hashcode/Exercises.md","filePath":"java/foundations/equals_hashcode/Exercises.md"}'),i={name:"java/foundations/equals_hashcode/Exercises.md"};function l(s,e,t,d,n,p){return o(),c("div",null,[...e[0]||(e[0]=[r('<h1 id="equals-hashcode-comparable-comparator-—-practice-exercises" tabindex="-1">equals / hashCode / Comparable / Comparator — Practice Exercises <a class="header-anchor" href="#equals-hashcode-comparable-comparator-—-practice-exercises" aria-label="Permalink to &quot;equals / hashCode / Comparable / Comparator — Practice Exercises&quot;">​</a></h1><hr><h2 id="topic-1-—-equals" tabindex="-1">Topic 1 — <code>equals</code> <a class="header-anchor" href="#topic-1-—-equals" aria-label="Permalink to &quot;Topic 1 — `equals`&quot;">​</a></h2><ol><li><p><strong><code>Person</code> class</strong> — fields <code>String name</code> and <code>int age</code>. Override <code>equals</code> following the five-rule shape:</p><ul><li>same reference shortcut</li><li>null-safe + type check</li><li>cast</li><li>compare fields</li></ul><p>Verify in <code>main</code>:</p><ul><li><code>p1.equals(p1)</code> → true (reflexive)</li><li><code>p1.equals(p2)</code> → true when same name+age (symmetric)</li><li><code>p1.equals(p3)</code> → false (different values)</li><li><code>p1.equals(null)</code> → false (null-safe)</li><li><code>p1.equals(&quot;Alice&quot;)</code> → false (type check)</li></ul></li></ol><hr><h2 id="topic-2-—-hashcode" tabindex="-1">Topic 2 — <code>hashCode</code> <a class="header-anchor" href="#topic-2-—-hashcode" aria-label="Permalink to &quot;Topic 2 — `hashCode`&quot;">​</a></h2><p><em>Coming after Topic 1 discussion.</em></p><hr><h2 id="topic-3-—-comparable" tabindex="-1">Topic 3 — <code>Comparable</code> <a class="header-anchor" href="#topic-3-—-comparable" aria-label="Permalink to &quot;Topic 3 — `Comparable`&quot;">​</a></h2><ol><li><p><strong><code>Person implements Comparable&lt;Person&gt;</code></strong> — sort by <code>age</code> ascending. Use <code>Integer.compare</code>, not subtraction.</p><p>Verify in <code>main</code>:</p><ul><li><code>Collections.sort(list)</code> on a <code>List&lt;Person&gt;</code> in random order → sorted by age</li><li><code>new TreeSet&lt;&gt;(list)</code> → also sorted by age</li></ul></li></ol><hr><h2 id="topic-4-—-comparator" tabindex="-1">Topic 4 — <code>Comparator</code> <a class="header-anchor" href="#topic-4-—-comparator" aria-label="Permalink to &quot;Topic 4 — `Comparator`&quot;">​</a></h2><p>All three in <code>main</code> of <code>EqualsHashCodePractice.java</code>:</p><ol><li>Sort <code>people</code> by name using <code>Comparator.comparing</code></li><li>Sort by age descending using <code>.reversed()</code></li><li>Sort by age ascending then name as tiebreaker using <code>.thenComparing</code></li></ol>',14)])])}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
